  "compound.critical.label": "CRIT +{xp} XP",
  "compound.critical.tooltip": "Uniquement les gains critiques réels ; les paiements normaux augmentent la réserve mais pas cette étiquette jaune. Un tirage reproductible par paiement réel : ×2 aux niveaux réels50–61 ; 10% de chance de×3 aux62–99. Sans plafond par paiement.",
  "compound.reward.critical": "Intérêts composés critiques : {chance}% de chance ; un tirage reproductible par paiement réel. Un critique multiplie le paiement sans plafond par {factor}.",
  "compound.reward.cadence": "Intérêts composés {percent}% toutes les {interval} ms ; sans plafond par paiement.",
  "compound.reward.payment": "Intérêts composés : chaque paiement admissible utilise la réserve actuelle d’XP non dépensés, y compris le paiement précédent déjà réglé ; sans plafond par paiement ni rattrapage hors ligne ou au rechargement.",
  "compound.reward.30": "Réserve d’XP actuelle ×0,025%, sans plafond par paiement. Les intérêts n’augmentent jamais les coûts d’XP. La réserve devient plus verte en grandissant ; la couleur affichée ne limite jamais le paiement.",
  "powerSettings.interestRulesLate": "Un seul flux sauvegardé d’intérêts composés : réserve actuelle non dépensée × taux réel × bonus d’XP gagnés/Joker/Poker, sans plafond par paiement. Un tirage reproductible par paiement réel : ×2 dès50 ; 10% de chance de×3 dès62. Dès80, la cadence acquise prend le relais ; le choix sauvegardé reste conservé.",
  "rush.start": "Boss Rush",
  "rush.confirm": "Commencer Boss Rush ?",
  "rush.accept": "Commencer Boss Rush",
  "rush.rules": "Cinq blindes de boss distinctes : une vraie boutique au départ et quatre entre les boss. L’XP des vraies mains, la Banque et les effets natifs des Potions et de Frénésie sont conservés. Aucun gain classique de parties, victoires, défaites, statistiques, tâches, collection ou victoires d’Emerald.",
  "rush.replace": "Ceci remplace votre partie actuelle. La progression du joueur, les réglages et les autres sauvegardes sont conservés.",
  "rush.boss": "Boss {n} / 5",
