  "rush.result": "{n} / 5 boss vaincus. Ce résultat ne compte pas comme victoire ou défaite classique.",
  "rush.abandon": "Termine Boss Rush sans enregistrer de défaite classique. L’XP, les déblocages, les sauvegardes et les réglages sont conservés. Les encaissements et choix de paquets en attente sont perdus.",
  "settings.emeraldPlacement.title": "Position d’Emerald",
  "settings.emeraldPlacement.left": "Emerald à gauche",
  "settings.emeraldPlacement.right": "Emerald à droite",
  "settings.emeraldPlacement.below": "Emerald en dessous",
  "settings.emeraldPlacement.note": "Sur les grands écrans, Gauche et Droite placent Emerald à côté de la table. Sur les écrans plus petits, ces alignements restent dans un espace réservé dessous. En dessous centre Emerald sous la table. Choisir une position suspend le suivi flottant sans effacer la préférence enregistrée. Activez le suivi pour le reprendre.",
  "expansion.reward.51": "Débloque8 interrupteurs de consommation dans Réglages : intérêts composés, argent passif, XP passifs, nom d’utilisateur, jeux de cartes, statistiques, enquêtes et marché. Chaque fonction DÉSACTIVÉE ajoute3 % d’AUTONOMIE, jusqu’à+24 % pour les8 ; aucun bonus de vitesse de charge. Choix sauvegardés et historique sont conservés, jamais supprimés. Charge essentielle, consommation, sauvegarde et récupération gardent leurs règles.",
  "expansion.compact.51": "8 interrupteurs dans Réglages · +3 % d’autonomie par fonction désactivée (max.+24 %)",
  "expansion.reward.52": "Les nouveaux XP gagnés doublent désormais : ×2 UNE SEULE FOIS. Les intérêts composés utilisent ce bonus sans plafond par paiement. Les gains déjà calculés ne doublent pas de nouveau. L’historique et les réserves sauvegardées ne sont pas réécrits.",
  "expansion.compact.52": "Nouveaux XP ×2 UNE FOIS avant plafonds · XP historiques inchangés",
  "expansion.reward.53": "La probabilité de CRIT de BASE augmente de1 point de pourcentage :1 %→2 %. Seule la probabilité de base change, pas les multiplicateurs CRIT existants ni les scores historiques.",
  "expansion.compact.53": "CRIT de base1 %→2 % (+1 point de pourcentage)",
  "expansion.reward.54": "Le score final gagne10 %, appliqué UNE SEULE FOIS puis arrondi vers le bas : floor(score final précédent ×1,10). Les effets des cartes et Jokers ne sont pas réappliqués ; les scores historiques ne changent pas.",
  "expansion.compact.54": "Score final ×1,10 UNE FOIS · arrondi vers le bas",
  "expansion.reward.55": "Vitesse de charge ×2. Le mode économie d’énergie continue de la diviser par deux ; ensemble, ils donnent la vitesse de base d’origine. Durée de session de charge et délai de récupération restent inchangés ; aucune recharge gratuite.",
  "expansion.compact.55": "Charge ×2 · économie d’énergie ×0,5 · mêmes session et récupération",
  "powerSettings.title": "Intérêts et consommation des fonctions",
  "powerSettings.interestTitle": "Intérêts composés · un seul flux sauvegardé",
  "powerSettings.interestRules": "Ces lignes règlent un seul flux d’intérêts composés, pas des paiements séparés. Chaque paiement utilise la réserve actuelle et son taux réel, avant les bonus d’XP gagnés/Joker/Poker. Sans plafond par paiement.",
  "powerSettings.fullUnlock": "Le choix complet de l’intervalle et du taux se débloque au niveau 44. Jusque-là, l’intervalle et le taux d’origine restent inchangés.",
  "powerSettings.row": "Niveau {level} · Intérêts composés",
  "powerSettings.rowLocked": "Cette ligne se débloque au niveau réel {level} ; elle modifiera le même choix sauvegardé.",
  "powerSettings.rowShared": "Reflète le même choix sauvegardé d’intervalle et de taux que les autres lignes débloquées.",
  "powerSettings.native": "D’origine · {ms} ms · {percent}% par paiement",
  "powerSettings.choice": "{ms} ms · {percent}% par paiement",
  "powerSettings.zero": "Le niveau réel 100 gagne 0 XP par les intérêts. Votre choix sauvegardé d’intervalle et de taux est conservé.",
  "powerSettings.featureTitle": "Consommation des fonctions · Niveau 51",
  "powerSettings.featureLocked": "Les interrupteurs des fonctions se débloquent au niveau 51. Les choix sauvegardés sont conservés ; en dessous de ce niveau, ils ne désactivent aucune fonction et n’ajoutent aucune autonomie.",
  "powerSettings.featureHelp": "Une case cochée indique une fonction explicitement activée dans vos choix sauvegardés. Le mode économie d’énergie peut suspendre l’activité en arrière-plan sans décocher ces cases.",
  "powerSettings.featureInterest": "Intérêts composés",
  "powerSettings.featurePassiveMoney": "Argent passif",
  "powerSettings.featurePassiveXp": "XP passifs",
