  "powerSettings.featureMarket": "Marché",
  "powerSettings.life": "Fonctions désactivées : {count}/8 · +{percent}% d’autonomie · ×{factor}",
  "powerSettings.lifeRules": "Chaque fonction désactivée ajoute 3% d’autonomie, jusqu’à +24% pour les huit. La consommation est divisée par 1 + 0.03 × nombre de fonctions désactivées ; la vitesse de charge ne change pas.",
  "powerSettings.lowPowerOn": "Le mode économie d’énergie est activé.",
  "powerSettings.lowPowerOff": "Le mode économie d’énergie est désactivé.",
  "powerSettings.lowPowerRules": "Le mode économie d’énergie suspend les intérêts composés, l’argent passif, les XP passifs et l’activité du marché en arrière-plan. Il conserve vos choix sauvegardés et votre historique.",
  "powerSettings.essentials": "Ces interrupteurs ne désactivent jamais la charge essentielle, la consommation de batterie, la sauvegarde ni la récupération. Leurs règles de temps restent applicables ; aucun historique n’est supprimé.",
  "expansion.deck.red": "+2 défausses à chaque manche.",
  "expansion.deck.blue": "+2 mains à chaque manche.",
  "expansion.deck.yellow": "Commencez avec $16 supplémentaires.",
  "expansion.deck.green": "Aucun intérêt. À l’encaissement d’une manche gagnée : $3 par main restante, $2 par défausse restante et $1 supplémentaire par manche terminée.",
  "expansion.deck.black": "+2 places de Joker ; -1 à la taille de la main. Aucune pénalité au nombre de mains.",
  "expansion.deck.magic": "Commencez avec Omen Globe, Crystal Ball et deux exemplaires de The Fool.",
  "expansion.deck.nebula": "Commencez avec Telescope et Observatory ; aucune pénalité de places de consommables.",
  "expansion.deck.ghost": "Exactement 20 % des sélections ordinaires de l’étal de la boutique sont spectrales. Commencez avec Hex et Ankh.",
  "expansion.deck.abandoned": "Commencez avec Ride the Bus et 40 cartes : sans valets, dames ni rois.",
  "expansion.deck.checkered": "Commencez avec exactement 80 cartes : 40 cœurs et 40 piques. Chaque enseigne ajoute A, K, Q, J, de 10 à 2, puis A à ses 26 cartes d’origine.",
  "expansion.deck.zodiac": "Commencez avec Tarot Merchant, Tarot Tycoon, Planet Merchant, Planet Tycoon, Overstock, Overstock Plus, Reroll Surplus et Reroll Glut.",
  "expansion.deck.painted": "+3 à la taille de la main ; -1 place de Joker.",
  "expansion.deck.anaglyph": "Obtenez deux Double Tags après chaque vraie victoire contre une blinde de boss.",
  "expansion.deck.plasma": "Équilibrez Chips et Mult à leur moyenne avant multiplication. Objectifs normaux des blindes.",
  "expansion.deck.erratic": "La graine sauvegardée fixe indépendamment entre 1 et 10 les mains, défausses, taille de main, places de Joker, places de consommables et Banque de départ ; rangs et enseignes sont tirés séparément.",
  "expansion.deck.copper": "Gagnez $5 supplémentaires à l’encaissement de chaque manche gagnée.",
  "expansion.deck.scholar": "Toutes les mains de poker, y compris les mains personnalisées, commencent au niveau 3.",
  "expansion.deck.twilight": "+2 à la taille de la main et +2 places de consommables.",
  "expansion.deck.prism": "Les 52 cartes de départ sont Wild. Commencez avec The Tribe.",
  "expansion.deck.sprout": "Les cartes de départ de rang 2–10 sont Bonus : +30 Chips lorsqu’elles marquent des points.",
  "expansion.reward.35": "Présentation de batterie plus nette ; les récompenses précédentes restent actives.",
  "expansion.reward.40": "Touchez le pourcentage de batterie pour voir la charge restante, l’autonomie estimée et les règles complètes.",
  "expansion.reward.42": "Les intérêts composés utilisent la réserve actuelle ×0,025%, sans plafond par paiement. Les900 ms d’origine restent sauf choix sauvegardé. La ligne de Réglages reste en lecture seule jusqu’au44 ; le niveau réel100 gagne0.",
  "expansion.reward.43": "+1 à la taille de main. Les intérêts composés restent réserve actuelle × taux réel × bonus d’XP gagnés/Joker/Poker, sans plafond ;900 ms et ×0,025% restent sauf choix sauvegardé.",
  "expansion.reward.44": "Débloque les11 combinaisons d’intervalle et de taux pour UN seul flux d’intérêts dans Réglages. Les lignes séparées des niveaux42/44/46/48/50 modifient le même choix sauvegardé, pas des paiements indépendants. Les deux options de500 ms sont distinctes : ×0,014 % et ×0,01 %. Un choix personnalisé remplace l’intervalle et le taux d’origine ; sans choix sauvegardé,800 ms et ×0,025 % restent en vigueur. sans plafond par paiement ; le niveau réel100 gagne0.",
  "expansion.reward.45": "Les 20 jeux de départ améliorés s’activent uniquement pour les NOUVELLES parties. Les parties sauvegardées gardent leurs avantages d’origine. Erratic tire séparément six statistiques de départ de 1 à 10 ; les modificateurs habituels restent applicables.",
  "expansion.reward.46": "Les nouveaux questionnaires ont 40 % de questions en moins : arrondi supérieur de l’original ×0,6, minimum 1, chez tous les fournisseurs. Questionnaires en attente, CAPTCHA, consentement, contrôles et récompenses sont conservés. Sans choix personnalisé sauvegardé, les intérêts d’origine paient toutes les700 ms à ×0,025 %, sans plafond par paiement. Un choix sauvegardé remplace l’intervalle et le taux d’origine ; la ligne de Réglages modifie le même flux unique. Le niveau réel100 gagne0.",
  "expansion.reward.47": "La mise maximale en Bourse passe à $20 fictifs selon le niveau réel du joueur. Délai de dix minutes, risques, retour brut ×1,5 et absence d’argent réel restent inchangés.",
  "expansion.reward.48": "Emerald se déplace 50 % plus vite en plus de son bonus E3 : ×1,5, ou ×1,8 avec E3. Les préférences de mouvement restent respectées. Sans choix personnalisé sauvegardé, les intérêts d’origine paient toutes les600 ms à ×0,025 %, sans plafond par paiement. Un choix sauvegardé remplace l’intervalle et le taux d’origine ; la ligne de Réglages modifie le même flux unique. Le niveau réel100 gagne0.",
  "expansion.reward.49": "Emerald gagne plus de 1 000 messages originaux et contextuels en anglais, espagnol et français : cartes, jeux, réflexions bienveillantes et idées respectueuses inspirées de la Bible. Il ne commente une enquête terminée qu’avec un reçu réel ; aucune prédiction de carte cachée ni du hasard.",
  "expansion.reward.50": "Interface plus nette et colorée, batterie aux reflets soignés et réglages allégés ; économie d’énergie, polices choisies et mouvement réduit restent respectés. Sans choix personnalisé sauvegardé, les intérêts d’origine paient toutes les500 ms : réserve actuelle ×0,025 %, sans plafond par paiement. Un choix sauvegardé remplace l’intervalle et le taux d’origine ; la ligne de Réglages modifie le même flux unique. Une seconde admissible peut contenir deux paiements d’origine ; le niveau réel100 gagne0.",
  "expansion.compact.35": "6 places Joker + sélection de 6 + Frenzy166 + nouvelles mains + $2/manche + batterie soignée",
  "expansion.compact.40": "Argent passif + détails via le pourcentage de batterie",
