  "battery.display": "Affichage de la batterie",
  "battery.decimals": "Décimales",
  "battery.compact": "Batterie compacte sous le nom d’utilisateur",
  "battery.displayHelp": "Affichage uniquement : aucune modification de charge, session ou repos. Le mode compact affiche le pourcentage dans la batterie ; touchez-la pour les commandes. Les commandes de récupération restent visibles à 0 %.",
  "battery.displaySaved": "Affichage de la batterie enregistré.",
  "battery.displayPaused": "L’enregistrement de l’affichage est incertain. Rechargez prudemment ; n’effacez rien et ne réessayez pas.",
  "battery.powerRules": "Clair est visiblement plus lumineux et Sombre plus atténué ; à 0 %, le jeu reste noir sauf Emerald et les commandes de récupération. Économie d’énergie divise la vitesse de charge par deux. Le niveau réel de joueur 55 double la vitesse ; les deux ensemble rétablissent la vitesse de base. Dès le niveau réel 51, chaque fonction désactivée ajoute 3 % d’autonomie : la décharge est divisée par 1 + 0,03 × fonctions désactivées (jusqu’à 8). Ce bonus n’accélère jamais la charge et ne modifie pas le repos.",
