  "battery.rate": "Chargeur {level} · +{rate} % par minute",
  "battery.session": "Session restante : {time}",
  "battery.rest": "Repos visible restant : {time}",
  "battery.upgrade": "Améliorer le chargeur · {coins} pièces du robinet",
  "battery.balance": "Pièces du robinet : {coins}",
  "battery.unsafePrice": "Le prochain prix dépasse la précision sûre ; gardez votre sauvegarde.",
  "battery.empty": "Batterie vide. Emerald, votre lampe, la charge, l’aide et les paramètres restent visibles.",
  "battery.rules": "Il s’agit d’une batterie FICTIVE du jeu, distincte de la batterie réelle de l’appareil et de son bonus de jetons. Elle commence à 100 % uniquement lors de votre activation explicite ou de votre première vraie action de jeu admissible. Elle n’est active qu’au niveau réel de joueur 25 ou plus. La décharge par défaut est de 1 point de pourcentage/minute ; Clair la remplace par 2, Sombre par 0,5, et Économie d’énergie remplace les trois par 0,2. Au-dessus de 80 %, la décharge double ; de 80 à 20 %, elle est normale ; de 20 à 5 %, la durée augmente de 50 % ; de 5 à 0 %, elle double. La luminosité suit la charge ; aucun curseur de luminosité.",
  "battery.chargeRules": "Cliquez sur Charger pour une session de 30 minutes admissibles. La charge positive REMPLACE la décharge : le chargeur 1 ajoute 0,80 point de pourcentage par MINUTE (24 points en 30 minutes) ; le chargeur 2 ajoute 0,82 (24,6 points), puis +0,02 par niveau. La charge s’arrête à 100 %, ou 80 % en mode Adaptative, puis un repos de 10 minutes admissibles commence. Les améliorations coûtent 20, 30, 40… pièces virtuelles du robinet, jamais la banque de poker. Aucun redémarrage automatique. Activer une cible adaptative inférieure à la charge actuelle arrête immédiatement la session.",
  "battery.clockRules": "Seul le temps de jeu visible, admissible et autorisé en écriture compte. Le temps masqué, hors ligne, d’un autre onglet, d’un dialogue protégé, d’un sondage ou d’un remplacement cloud/emplacement n’est jamais rattrapé. Les durées restantes de session et de repos survivent au rechargement. Chaque seconde active de charge peut produire un son natif après votre geste audio ; les réglages muet/effets s’appliquent, sans rafale de rattrapage.",
  "battery.notices": "Les alertes ne surviennent qu’au franchissement réel vers le bas de 10 %, 5 % et 3 %, une fois par seuil jusqu’à une recharge au-dessus. Afficher ou recharger la page ne déclenche ni alerte ni récompense.",
  "battery.warning": "Batterie fictive faible : {percent} %. La charge est accessible depuis son contrôle.",
