  "chill.cooldown": "Prédiction prête après {seconds}s de temps visible admissible.",
  "chill.rules": "Comment jouer",
  "chill.baccaratRules": "Cartes : as = 1 ; de 2 à 9, la valeur indiquée ; 10/J/Q/K = 0. Seul le dernier chiffre du total compte (modulo 10). La distribution alterne joueur, banquier, joueur, banquier. Un 8 ou 9 initial d’un côté arrête les deux mains. Sinon, le joueur tire avec 0–5 et reste avec 6–7. Si le joueur reste, le banquier tire avec 0–5. Si le joueur tire une troisième carte x : le banquier tire avec 0–2 ; avec 3 sauf si x = 8 ; avec 4 si x = 2–7 ; avec 5 si x = 4–7 ; avec 6 si x = 6–7 ; et reste toujours avec 7. Le total final le plus élevé gagne ; deux totaux identiques font égalité.",
  "chill.highlowRules": "L’as est fort : 2–10, J, Q, K, A. Lancer et Suivante sauvegardent son choix indépendant 50/50 Plus haut ou Plus bas avant ta décision ; il ne voit jamais la prochaine carte cachée. Une nouvelle prédiction exige cinq secondes visibles admissibles : le temps caché, les dialogues, animations, déconnexions et rechargements ne se rattrapent pas. Ta bonne prédiction donne 25 XP natives de base ; le bonus du niveau 52 s’applique une fois. Une prédiction historique en attente garde ses 10 XP de base. Son bon choix donne +1 FP. Des valeurs égales ne donnent rien. Aucune mise ni score compétitif. Un sabot indépendant de 52 cartes est utilisé ; Suivante en ouvre un autre après le dernier résultat. Un résultat sauvegardé ne paie plus ; quitter ou recharger conserve la table.",
  "chill.speechReady": "Une table tranquille, quelques cartes… prenons notre temps.",
  "chill.speechBaccarat": "La manche est terminée. J’aime jouer avec toi.",
  "chill.speechPrediction": "J’ai choisi. Selon toi, quelle sera la prochaine carte ?",
  "chill.speechResult": "Cette carte avait ses propres idées. On continue quand tu veux.",
  "interest.cap43.note": "Les intérêts composés utilisent la réserve actuelle d’XP non dépensés à CHAQUE paiement : taux d’origine0,01% aux niveaux réels20–25,0,015% aux26–29 et0,025% aux30–79 sauf choix sauvegardé ; dès80, cadence et taux acquis prennent le relais. Sans plafond. Les bonus d’XP gagnés, Joker Exp physique et Poker natif s’appliquent une fois. Un tirage reproductible par paiement réel : ×2 aux50–61 ; 10% de chance de×3 aux62–99. Chaque règlement conserve les coûts des niveaux franchis et utilise la réserve résultante précédente. Le niveau réel100 gagne0. Niveau15, manuel22, Potion Exp et bonus Slots non concernés ne multiplient pas les intérêts. Connaissance et intérêts en argent restent séparés. Anciens reçus et réserves inchangés. Temps visible admissible uniquement ; aucun rattrapage masqué, hors ligne ou au rechargement.",
  "interest.currentCap": "Les intérêts composés n’ont pas de plafond par paiement. Limite des anciens reçus : {value1}.",
  "interest.cap43.reward": "Les intérêts composés n’ont pas de plafond.900 ms et ×0,025% restent sauf choix sauvegardé ; le niveau réel100 gagne0.",
  "interest.cap43.compact": "Intérêts composés · sans plafond",
