  "settings.usernameRules": "Utilisez un pseudo inventé, sans données personnelles. Longueur : 3–24 caractères, parmi les lettres ASCII, les chiffres, les traits de soulignement et les traits d’union. Les noms ne sont pas uniques à l’échelle mondiale et n’identifient pas un compte cloud.",
  "settings.usernamePending": "Rien n’est enregistré avant votre confirmation.",
  "settings.usernameNote": "Le pseudo aléatoire initial est calculé localement à partir de la génération de cet emplacement, sans sauvegarde supplémentaire ni tirage dans le générateur aléatoire du jeu. Un pseudo personnalisé confirmé est conservé dans les paramètres de cet emplacement et n’est inclus que lors d’une exportation ou d’une sauvegarde cloud manuelle. Le pseudo généré au départ n’est pas une identité cloud.",
