  "cloud.replaceNote": "Sauvegarder dans le cloud remplace la progression cloud de ce compte uniquement après confirmation si une sauvegarde existe déjà. Charger remplace seulement la progression, la partie et les paramètres de l’emplacement local sélectionné après confirmation, en créant d’abord une sauvegarde locale durable de cet emplacement. Les deux autres emplacements ne changent pas. Se connecter, récupérer un mot de passe ou changer de compte ne transfère jamais la progression.",
