  "catalog.card.hidden.description": "Face cachée pour cette blinde.",
  "aux.levels.ui.920b817ce65c": "À quoi servent principalement les Jokers ?",
  "aux.levels.ui.c013b30576f3": "Modifier le score et ajouter des bonus",
