  "aux.levels.ui.d61fa4e22175": "Progression du plafond de {value1} à {value2} : {value3} / {value4} Antes",
  "aux.levels.ui.298aaf6a33a2": "Après le niveau {value1} : gagnez petite, grosse et boss dans l’ordre, dans la même partie et le même Ante. Les blindes passées ne comptent jamais. Le plafond suivant repart avec un nouveau compteur. Toute l’XP est conservée.",
  "aux.levels.ui.12b50fb8ec34": "{value1} pour débloquer le plafond {value2}",
  "aux.levels.ui.cc419e152ce7": "Plafond actuel : {value1}. {value2} Chaque Ante complet exige des reçus de VICTOIRE petite, grosse et boss dans l’ordre, dans la même partie et le même Ante ; les blindes passées ne comptent jamais. Chaque plafond repart de zéro : 10 / 25 / 50 / 100 Antes complets après les niveaux 10 / 20 / 30 / 35. Les niveaux et plafonds déjà acquis restent débloqués ; aucun crédit historique d’Ante complet n’est inventé. Toute l’XP est conservée.",
