  "aux.levels.ui.fad78482b16c": "XP en réserve : {value1} · toute l’XP conservée",
  "aux.levels.ui.fca7b58aad46": "+{value1} XP en réserve · plafond {value2}",
  "aux.levels.ui.9218684158d5": "Plafond au niveau {value1} · remplissez sa condition d’Antes",
  "aux.levels.ui.90dcab158c44": "Intérêts d’XP +{value1} XP/s",
  "aux.levels.ui.ff75e0d3a881": "{value1} Réserve actuelle : {value2} XP ; seconde suivante : {value3} XP réels. La couleur reste neutre jusqu’à 1 XP/sec, atteint progressivement le jaune à 2 XP/sec, puis verdit jusqu’à 5 XP/sec.{value4}{value5}{value6}{value7}",
  "aux.levels.ui.f56e82a7ade0": "Mode déplacement · enregistrement des dispositions de panneaux mobiles · Thèmes de table personnalisés · XP requise pour tous les niveaux divisée par deux · {value1}",
  "aux.levels.ui.fd983ce532d1": "Interface des niveaux de joueur améliorée · XP, récompenses et états terminés/verrouillés plus clairs · animations vertes de gain +XP et reflet blanc rebondissant sur la barre d’XP · {value1}",
  "aux.levels.ui.6ee23633b64b": "Coûts futurs en XP réduits de 40% supplémentaires, cumulables avec le niveau 10 (30% des coûts d’origine) ; aucun remboursement · +1 main et défausse à chaque boss · Interface plus claire et boutons plus fluides · couleurs enrichies et lueurs douces · montants en dollars jaunes · petite blinde bleue, grosse jaune, boss rouge · {value1}",
  "aux.levels.ui.9cf1b5d5fea3": "{value1} · Coûts futurs en XP réduits de 30% supplémentaires dès 30→31 ; se cumule avec la division par deux du niveau 10 et la réduction du niveau 20 (21% de l’original avant arrondi entier et potions) ; aucun remboursement · Photos personnalisées des figures (J/Q/K) · Interface améliorée et couleurs de table enrichies · Importez vos images de fond et de dos de carte · Personnalisez police et couleur de tous les textes dans les Paramètres ; réinitialisez le texte sans modifier les photos ni la disposition des panneaux",
  "aux.levels.ui.2eb04acd9701": "Niveau maximal de joueur {value1} atteint. Les récompenses précédentes restent actives.",
