  "aux.levels.ui.54358ea00495": " pièces",
  "aux.levels.ui.5973eb91d256": "Intérêts composés · en pause",
  "aux.levels.ui.22a33b4ef0b3": "un scarabée vert",
  "aux.levels.ui.e445541d4be7": "Éclat coloré supplémentaire · reflets statiques bleus, rouges, dorés et verts ; couleurs d’origine, texte lisible et réglages d’animation préservés",
  "aux.levels.ui.5dae15c973e6": "Musique de boss plus dramatique · tension croissante, harmonie mouvante et rythmes tendus, avec un apogée renforcé pour le boss final",
  "aux.levels.ui.1a62db1746a4": " · Emerald disponible comme compagne : votre photo de scarabée, des conseils uniquement sur le jeu et des encouragements",
  "aux.levels.ui.5e10e5839a2d": " · Progression d’Emerald débloquée : barre verte E1–E10 sous la photo pendant une partie ; les nouvelles victoires complètes obtenues au niveau réel 10+ font avancer chaque étape",
  "aux.levels.ui.15734bbd0c0d": " · Frenzy débloqué : 500 déclenchements de cartes marquant réellement activent 10 secondes de Frenzy arc-en-ciel et ×1.5 au Mult final (166 déclenchements dès le niveau 35)",
  "aux.levels.ui.f54a86a01acf": " · Six places de Joker de base · Sélectionnez jusqu’à 6 cartes à jouer ou défausser · Frenzy exige désormais 166 déclenchements de cartes marquant réellement · Double-Triple of a Kind : 120 Chips ×10 Mult, +20 Chips/+4 Mult par niveau ; Venus Rock · Six of a Kind : 150 Chips ×10 Mult, +30 Chips/+3 Mult par niveau ; Planet Y",
  "aux.levels.ui.92fb25712016": "Musique débloquée · Changez de nom dans Paramètres → Changer de nom d’utilisateur → Confirmer",
  "aux.levels.ui.cc4d1a7109e9": "Intérêts débloqués · Présentation plus claire : statistiques compactes, commandes Partie / Outils regroupées et plus de place pour les cartes",
  "aux.levels.ui.c3986e8d8c85": "Quatre places de Joker de base",
  "aux.levels.ui.2ec3a602bafa": "Cinq places de Joker de base · Musique émouvante débloquée : Last Chance",
  "aux.levels.ui.80220b003c53": "Abréviations numériques intelligentes",
  "aux.levels.ui.a6831b469325": "XP passive manuelle · 0.01/sec, session de 10 minutes puis attente de 5 minutes",
  "aux.levels.ui.1bbfd47eb010": "L’XP passive passe à 0.025 par seconde pour des sessions de 10 minutes, suivies d’une attente de 5 minutes",
  "aux.levels.ui.14471419e112": "Potions débloquées · conservez-en 2, buvez pour un effet de 2 minutes. Victoires de boss : chance de base de potion de 1 sur 10, plafonnée à 5 sur 10.",
  "aux.levels.ui.7909190c155b": "Les sessions d’XP passive durent 20 minutes",
  "aux.levels.ui.20ad162e567b": "Débloque les sondages Theorem Reach · L’attente d’XP passive passe à 4 minutes",
  "aux.levels.ui.c9cf9b6a4705": "XP doublée à partir de maintenant",
  "aux.levels.ui.2ef761428a63": "Les sessions d’XP passive durent 30 minutes · L’XP passive de base passe à 0.05/sec (0.1 XP/sec avec l’XP doublée du niveau 15)",
  "aux.levels.ui.00991737774c": "+25% de chance permanente · probabilités indiquées ×1.25 ; se cumule avec Oops et plafonne à 100%",
  "aux.levels.ui.6251513eba38": "Débloque les sondages Bitlabs · Gagnez $1 à chaque déclenchement d’un effet spécial de boss actif · une récompense par activation de capacité, pas par carte affectée",
  "aux.levels.ui.62ea740ddc00": "Bourse · prédictions fictives en dollars du jeu utilisant les prix BTC publics de Binance ; aucun argent réel",
  "aux.levels.ui.5ce6478a32d8": "Animations 20% plus rapides · +20% d’XP manuelle (jeu, sondages et robinet) ; pas d’XP passive, de Knowledge ni d’intérêts",
  "aux.levels.ui.4c33d5827537": "+$1 à chaque encaissement de manche gagnée",
  "aux.levels.ui.b22c96f74381": "Tout dans la boutique de partie coûte $1 de moins après les remises existantes ; minimum $0 · Bande-son Casino débloquée",
  "aux.levels.ui.ff12575787c7": "Débloque les sondages CPX Research · Robinet de pièces · 10 XP de base par réclamation réussie, avec bonus manuel du niveau 22, Exp Potion et Exp Jokers (pas le niveau 15). Commence au taux de tâche de 50% ; atteignez l’Ante 4 dans 1 partie admissible par jour pour le taux complet. Les réclamations répétées réduisent le palier quotidien de réclamation.",
  "aux.levels.ui.7b8c17e2aa43": "Les intérêts composés passent à réserve actuelle ×0,015%, sans plafond",
  "aux.levels.ui.e05cf7cff27b": "Deux bandes-son originales supplémentaires : Starlight Felt et Copper Groove",
  "aux.levels.ui.20bfdc60ebb9": "Notification non répétitive en jeu quand le robinet est prêt ; aucune autorisation du navigateur",
  "aux.levels.ui.4e8ce5229a16": "Cinq jeux de cartes originaux et deux mises originales se débloquent à l’écran principal",
  "aux.levels.ui.1982d56e4324": "Commandes plein écran et sortie ; réduire la fenêtre système reste une commande de l’appareil",
  "aux.levels.ui.0b02333ddd7f": "Fusionnez deux potions conservées en gardant les deux effets pour une durée unique de 120 secondes",
  "aux.levels.ui.268db3145f3b": "+$2 à la fin de chaque manche gagnée",
  "aux.levels.ui.172c3a8a5b8f": "Emerald : appuyez sur la photo ou la barre de progression pour sa propre feuille de route, avec le niveau actuel encadré ; progression et pourcentage des nouvelles victoires · Parole automatique pendant 5 minutes, puis 1 minute d’attente · Enregistrements sous licence de George Street Shuffle et Mining by Moonlight ; Poker Face ouvre exactement le titre officiel Spotify en externe, pas un son hors ligne",
  "aux.levels.ui.4091e1349b2d": "Emerald reflète un éclat vert émeraude renforcé",
  "aux.levels.ui.c0955075c2a3": "Emerald apparaît sur tous les écrans, sondages compris · Exactement “Trick Question!!!” uniquement sur une véritable question de vérification d’attention",
  "aux.levels.ui.7d1c4602dc17": "Revenus passifs sous le robinet de pièces, reprenant la disposition de l’XP passive avec lueur jaune et symboles $ € £ · +$0.01 par seconde observable au premier plan vers le solde de la partie actuelle pendant 10 minutes, puis 5 minutes d’attente · Un solde plus élevé donne un son d’argent plus aigu ; aucun rattrapage hors ligne",
  "aux.levels.ui.67a11fa93b06": "Couleurs texturées enrichies, lumières réfléchies, interface plus claire et éclat supplémentaire ; l’encre des questions et les médias des réponses aux sondages ne changent pas",
  "aux.levels.ui.ec808c9444d1": "Les sessions de revenus passifs durent 20 minutes, puis 4 minutes d’attente ; les sessions existantes gardent leur durée initialement fixée",
