  "aux.levels.ui.cd3ad306d393": "Votre niveau persiste entre les parties. Les récompenses s’appliquent immédiatement ; l’XP à un plafond verrouillé est conservée, pas perdue.",
  "aux.levels.ui.b09426842348": "XP d’action de base : 1 par $1 réellement dépensé, +3 par achat de Joker en boutique, +3 par utilisation réussie de tarot, +5 par petite/grosse blinde passée et 1 par carte jouée. Victoires petite/grosse/boss : 3/5/10 × Ante. Gains positifs de niveau de main : 3 XP chacun. Les multiplicateurs du niveau 15, d’Exp Potion, des Exp Jokers physiques actifs et du bonus manuel du niveau 22 s’appliquent aux récompenses d’action. Les intérêts composés n’ont pas de plafond ; Connaissance garde ses règles natives distinctes.",
