  "aux.survey.runner.517df2548a83": "Sondage fictif — Balatro Online",
  "aux.survey.runner.22897330cc70": "SONDAGE ORIGINAL DU JEU",
  "aux.survey.runner.bafb856e832f": "Utilisez des réponses fictives, jamais de véritables informations personnelles. Local uniquement · monnaie du jeu uniquement · aucune affiliation à une société de sondages.",
  "aux.survey.runner.8eb12781825f": "Les étoiles déterminent la qualité de présentation, jamais la récompense sauvegardée.",
  "aux.survey.runner.94c10e6cc839": "Le texte des réponses est net",
  "aux.survey.runner.bf97d22268f8": "Garder les réponses nettes",
  "aux.survey.runner.8b962911ee56": "Sondage en pause",
  "aux.survey.runner.f107b1d67727": "Réessayer le sondage sauvegardé",
  "aux.survey.runner.70941ad4097c": "Merci d’avoir terminé le sondage !",
  "aux.survey.runner.96f577aca304": "Ce sondage est terminé",
  "aux.survey.runner.444045937213": "Votre état terminé est enregistré sur cet appareil. Revenez au jeu pour récupérer la récompense en monnaie du jeu.",
  "aux.survey.runner.20f3bb62c481": "Retour à votre jeu dans un instant…",
  "aux.survey.runner.a0603f603aeb": "CAPTCHA local",
  "aux.survey.runner.2980a0aedea0": "Bienvenue dans le sondage !",
  "aux.survey.runner.bd1521f23f8e": "Une simple vérification locale du jeu, pas un véritable service de sécurité anti-bot. Aucun CAPTCHA externe, suivi ni compte n’est utilisé.",
  "aux.survey.runner.822dca242316": "Vérifier le CAPTCHA local",
  "aux.survey.runner.e826c9f10c83": "Le CAPTCHA local est terminé. Prenez votre temps et utilisez des détails inventés. Votre questionnaire et la récompense de jeu indiquée sont enregistrés sur cet appareil.",
  "aux.survey.runner.1f1629fa4522": "Ce questionnaire comprend des vérifications de consignes claires, des tableaux de préférences de sept sur sept et des choix de vraies vidéos de nature. Les vidéos commencent en pause et sans son. Leur visionnage est facultatif ; chaque choix vidéo a une description textuelle si son aperçu est indisponible.",
  "aux.survey.runner.a251ae564422": "Ce questionnaire comprend des vérifications de consignes claires et des tableaux de préférences de sept sur sept. Les médias peuvent être mis en pause ; les images réelles facultatives disposent d’une illustration locale de secours.",
  "aux.survey.runner.4a6d1d0dba30": "Commencer le sondage",
  "aux.survey.runner.c4aa6ca09e7d": "Mettre en pause et revenir au jeu",
  "aux.survey.runner.3313fdb22201": "Évaluez chaque caractéristique",
  "aux.survey.runner.3d377ae910dc": "Caractéristique",
  "aux.survey.runner.e11073782fc9": "Images réelles facultatives de fleurs · aperçu CC0 inclus. La question concerne l’illustration locale ci-dessus, pas cet aperçu.",
  "aux.survey.runner.834c386da51b": "L’aperçu d’images réelles commence en pause. La lecture est facultative ; la question illustrée fonctionne toujours hors ligne.",
  "aux.survey.runner.0d18fbe3b6ab": "Images réelles facultatives de fleurs, distinctes de la question",
  "aux.survey.runner.9a4e1838014c": "Aperçu réel indisponible. L’illustration locale de secours ci-dessus reste disponible hors ligne.",
  "aux.survey.runner.f1fb31a7f388": "Choisissez un extrait. L’aperçu est facultatif ; les commandes de lecture ne sélectionnent pas de réponse.",
  "aux.survey.runner.90bd7eed357d": "Raccourci, redimensionné et sans son.",
  "aux.survey.runner.d472e3b48e95": "Commence en pause · visionnage facultatif. Choisissez ci-dessous à l’aide de la vidéo ou de la description.",
  "aux.survey.runner.9dc5dfb616a8": "Aperçu indisponible. Vous pouvez toujours choisir cette option à l’aide de sa description ; aucun visionnage n’est requis.",
  "aux.survey.runner.0e570ca6fabe": "Source",
