  "aux.surveys.ui.741d6d25300e": "Petites questions. Nouvelles possibilités.",
  "aux.surveys.ui.2ec1e7d1b01e": "Simulations locales originales · aucune affiliation aux fournisseurs · aucune véritable donnée personnelle.",
  "aux.surveys.ui.d67bf8fc2edc": "Médailles disponibles",
  "aux.surveys.ui.926f880152df": "Récompenses de base doublées et deux fois plus de questions · 20–200 questions.",
  "aux.surveys.ui.2eb9bc27f1e6": "Moitié des récompenses de base · les demi-unités exactes sont conservées · 10–100 questions.",
  "aux.surveys.ui.836a7950a71c": "Récompenses de base · 10–20 pièces ou Médailles, ou 100–300 XP de base. Les événements locaux simulés améliorent occasionnellement les NOUVELLES offres uniquement. Les récompenses promotionnelles sont arrondies au prochain multiple supérieur de 0.5 unité de jeu ; déjà inclus dans la récompense indiquée.",
  "aux.surveys.ui.02f7055f0f8c": "Chaque offre choisit indépendamment pièces, Médailles ou XP avec une chance de 1 sur 3. L’XP affichée est l’XP DE BASE ; les bonus d’XP manuelle débloqués de niveau 15 / niveau 22, les Exp Joker possédés et Exp Potion active s’appliquent au versement.",
  "aux.surveys.ui.ae31f241d489": "Les étoiles déterminent l’apparence du questionnaire et la qualité des médias : 1★ brouillon, 2★ basique, 3★ standard, 4★ soigné, 5★ studio. Le texte des réponses à peu d’étoiles peut être rendu plus net. Les nouveaux questionnaires commencent par un CAPTCHA local, puis Bienvenue dans le sondage ! Les anciens questionnaires sauvegardés gardent leurs questions d’origine.",
  "aux.surveys.ui.679d81586b02": "HOT / Nouveau · Ajout récent : 1 sur 5, simple étiquette. TOP · récompense du fournisseur 4× : 1 sur 25, déjà incluse ci-dessous. Les badges indépendants peuvent apparaître ensemble ; TOP n’ajoute aucune question.",
  "aux.surveys.ui.f4ebccf59c8d": "Votre prochaine récompense commence ici",
