  "aux.emerald.ui.a59ae4dc9c47": "Conseil suivant automatique toutes les 10 secondes pendant 5 minutes, puis 1 minute d’attente. Se met en pause si indisponible ; la fenêtre de temps continue de s’écouler. Aucune voix, discussion ni cadeau supplémentaire. Cet onglet uniquement : le rechargement annule.",
