  "aux.daily.tasks.ui.b4e6a5cc8218": "La progression repart de zéro à minuit à Tenerife (Atlantic/Canary). Gardez toutes les Médailles en banque d’un jour à l’autre et en nouvelle partie. Seules les nouvelles actions réelles comptent : score d’une main, cartes jouées (pas les redéclenchements), revenus bruts du jeu, victoires de blinde (pas les passages) et utilisations de tarot. Aucun argent, pièce ni XP supplémentaire.",
  "aux.potions.ui.5990a93c751c": "CRIT de base de 2% · {value1}% actuellement · perd 1 HP / carte sélectionnée",
  "aux.potions.ui.aa6599e59da9": "+{value1} Mult à la FIN du calcul du score · pas ×day",
  "aux.potions.ui.c33b600b9d17": "CRIT de base de 2.5% · {value1}% actuellement / déclenchement de score · ×2 Mult",
