  "aux.potions.ui.d8286040847e": "$1 d’intérêts / $3 détenus · plafond normal",
  "aux.potions.ui.be4ea8943a68": "1 XP fixe / seconde · XP passive manuelle uniquement",
  "aux.potions.ui.3c54793e2903": "½ des nouvelles attentes passives / du robinet · Bourse toujours à 10m",
  "aux.potions.ui.e2ba77631dc0": "+1 niveau supplémentaire / planète · pas Black Hole",
  "aux.potions.ui.262b74e0e274": "Toute carte non-Stone compte comme toutes les enseignes",
  "aux.potions.ui.ba127e18dccd": "1 sur 20 fixe au début du boss · désactivation temporaire",
  "aux.potions.ui.ebf75ae56d42": "Coûts d’XP du joueur ×0.9 · niveaux acquis conservés",
  "aux.potions.ui.3a6fc3c3ad74": "Durées des animations de score ×0.7 · aucun changement de score ni de minuterie",
