  "aux.stats.43ae3265b99f": "Thèmes",
  "aux.stats.d7a7ef71125f": "Le niveau 12 remplace l’ancien déblocage de désactivation de boss une fois par partie. Conservez deux potions ; un seul effet actif de 2 minutes à la fois.",
  "aux.stats.2a195cdc5e77": "Chance du joueur",
  "aux.stats.83a6c591b7f6": "Base (×1)",
  "aux.stats.b5c7345ef43c": "Niveau 17+ : probabilités de déclenchement indiquées ×1.25, cumulables avec Oops actif ×2 par exemplaire ; plafonnées à 100%. La rareté et les éditions de la boutique ne changent pas. La collection garde les probabilités de base.",
  "aux.stats.2665c8532928": "Argent par effet de boss",
  "aux.stats.dfd4cdecceff": "Niveau 19+ : $1 par véritable activation d’un effet spécial de boss actif. Les lots de cartes comptent une seule fois ; les capacités supprimées, consultations, rechargements et changements administratifs limités aux potions ne paient rien. Règlement après les effets de l’action native.",
  "aux.stats.4270505ad356": "Mains de boss supplémentaires",
