  "aux.stats.971d8583cbc3": "Chance effective de CRIT de base combiné",
  "aux.stats.87e6c43b902c": "Aucune partie active",
  "aux.stats.e457ced72023": "Multiplicateur d’XP de potion",
  "aux.stats.5d84ae847ae2": "Multiplicateur de chance de potion",
  "aux.stats.71b87005e846": "Bonus temporaire de taille de main",
  "aux.stats.ac7c949f1211": "Inactive",
  "aux.stats.0dc06c50a558": "Taux d’exigence en XP",
  "aux.stats.ca04e0349f22": "Une bouteille active pendant 2 minutes réelles. Les mélanges du niveau 33 conservent tous les effets distincts pour une durée commune unique ; Gaming+Critical donnent 4.5% de CRIT de base des potions. Probabilités finales plafonnées à 100%. Les potions de boss sont plafonnées à 5 sur 10 ; Boss-disabler Potion reste fixée à 1 sur 20. Les minuteries de prédiction de la Bourse ne sont pas des délais de réutilisation.",
  "aux.stats.4acca865dbb6": "Sessions d’XP passive",
  "aux.stats.e6a7cb43dc04": "Session passive",
  "aux.stats.f4ccae29e1bb": "En cours",
  "aux.stats.8dec2f39b28d": "En attente",
  "aux.stats.1a4f630ac1b6": "Arrêtée",
  "aux.stats.30ef05ccbf74": "Attente de reprise passive",
  "aux.stats.97f70cda8c43": "Attente passive actuelle",
  "aux.stats.2fc5e288f610": "Sessions lancées",
  "aux.stats.184fbde40bf2": "Sessions terminées",
  "aux.stats.36f40a35fc14": "Paiements passifs crédités",
  "aux.stats.4a9df964e016": "Secondes passives payées",
  "aux.stats.2a633f2f20aa": "XP passive gagnée",
  "aux.stats.9d1399441b1c": "Versements de cette session",
  "aux.stats.4ce16a300404": "XP par paiement passif",
  "aux.stats.105943d6bf25": "Intervalle de paiement passif",
  "aux.stats.c7ac106ca106": "Durée de session débloquée",
  "aux.stats.b70edc427fba": "Temps de session restant",
  "aux.stats.84d8669b9135": "Niveau 9 : 0.01 XP par seconde. Niveaux 11–15 : 0.025 XP de base par seconde ; niveau 16+ : 0.05 XP de base par seconde jusqu’au niveau 20. L’XP passive est doublée dès le niveau 15, donc le niveau 16 donne 0.1 XP par seconde. Les intérêts composés utilisent la réserve actuelle d’XP non dépensés à CHAQUE paiement : taux d’origine0,01% aux niveaux réels20–25,0,015% aux26–29 et0,025% aux30–79 sauf choix sauvegardé ; dès80, cadence et taux acquis prennent le relais. Sans plafond. Les bonus d’XP gagnés, Joker Exp physique et Poker natif s’appliquent une fois. Un tirage reproductible par paiement réel : ×2 aux50–61 ; 10% de chance de×3 aux62–99. Chaque règlement conserve les coûts des niveaux franchis et utilise la réserve résultante précédente. Le niveau réel100 gagne0. Niveau15, manuel22, Potion Exp et bonus Slots non concernés ne multiplient pas les intérêts. Connaissance et intérêts en argent restent séparés. Anciens reçus et réserves inchangés. Temps visible admissible uniquement ; aucun rattrapage masqué, hors ligne ou au rechargement. Les nouvelles sessions durent 10 minutes jusqu’au niveau 13, puis 20/30/50/60 minutes aux niveaux 13/16/33/44 ; le niveau 22 ne prolonge plus les sessions. Attente de cinq minutes jusqu’au niveau 14, puis quatre minutes ; atteindre le niveau 14 raccourcit aussi une attente en cours. Aucune reprise automatique. Exp Potion double l’XP passive ordinaire ; Knowledge rapporte 1 XP par seconde multiplié uniquement par les Exp Jokers physiques actifs ; le niveau 15, Exp Potion et le bonus manuel du niveau 22 sont exclus. Cooldown Potion peut diviser une attente par deux une seule fois, sans jamais cumuler jusqu’au quart.",
  "aux.stats.7c321789b917": "Robinet de pièces virtuelles",
  "aux.stats.90a4760bbfb6": "Solde de pièces virtuelles",
  "aux.stats.cec81120bc86": "Réclamations du jour",
  "aux.stats.90db295b4c5a": "Gagné aujourd’hui · pièces virtuelles",
  "aux.stats.a5950c40b229": "Parties quotidiennes jusqu’à l’Ante 4",
  "aux.stats.f5db6b52c254": "Taux de récompense actuel",
  "aux.stats.0046aebd5583": "XP par réclamation réussie",
  "aux.stats.111c04fc81db": "Base 10 ; s’appliquent le bonus manuel 22 ×1.2, Exp Potion ×2 et les Exp Jokers physiques actifs ×1.2 chacun. Le multiplicateur du niveau 15 ne s’applique pas.",
  "aux.stats.7940d1d5c626": "Niveau du robinet",
  "aux.stats.e017d12ee6b6": "Réclamations réussies",
  "aux.stats.acb428e6e0a2": "Réclamations vers le niveau actuel du robinet",
  "aux.stats.7802d9410317": "Réclamations requises pour le niveau suivant du robinet",
  "aux.stats.e82682d5e356": "Récompense actuelle · pièces virtuelles",
  "aux.stats.82943eb70695": "Attente de nouvelle réclamation",
  "aux.stats.935b7d167ac3": "Attente actuelle restante",
  "aux.stats.f2a3669367bb": "Déblocages permanents de Jokers avec des pièces",
  "aux.stats.9b5bec7c21ea": "Pièces virtuelles gagnées depuis le début",
  "aux.stats.08f9902bddeb": "Pièces virtuelles dépensées depuis le début",
  "aux.stats.c715b03dc462": "Les pièces virtuelles ne sont pas de l’argent. Les récompenses fractionnaires sont conservées exactement, y compris les centièmes en attente. La tâche quotidienne d’Ante 4 et les paliers de réclamation repartent de zéro à minuit Atlantic/Canary ; les réclamations réussies donnent 10 XP de base avec les multiplicateurs du bonus manuel 22, d’Exp Potion et des Exp Joker physiques actifs, mais pas du niveau 15. Les revenus historiques de pièces depuis le début ne peuvent pas être reconstitués à partir du niveau ou du solde actuel du robinet.",
  "aux.stats.c5b17c8cdb02": "Nouveaux reçus de progression depuis cette mise à jour",
  "aux.stats.52bf2c9c2b8d": "XP de base des reçus de jeu",
  "aux.stats.cb3f65a07fd0": "Dépenses réelles, achats de Jokers, utilisations de tarot, cartes jouées, blindes passées/gagnées et reçus de niveau de main avant multiplicateurs. L’XP passive est indiquée séparément.",
