  "aux.stats.eda52f1c5379": "La découverte suit le registre local existant, y compris ses entrées initiales ; parcourir un catalogue n’est pas une acquisition.",
  "aux.stats.38713b8f61f8": "Aucune victoire de mise enregistrée",
