  "aux.stats.974de6192c45": "Seuls les gagnants enregistrés sont indiqués ; aucune possession historique non enregistrée n’est déduite.",
  "aux.stats.9b7346d9cdb4": "Référence des probabilités auditée",
  "aux.stats.fdbdbb49ef45": "La référence des probabilités attend son audit. Aucune probabilité non vérifiée n’est affichée.",
  "aux.moving.panels.8d3220f41193": "Commandes des panneaux du mode déplacement",
  "aux.moving.panels.6147adfc7f10": "Mode déplacement",
  "aux.emerald.blackjack.ui.7eb66e5118fc": "MAX · {value1} FP",
  "aux.emerald.blackjack.ui.bfb414bf51ab": "{value1}/{value2} FP",
  "aux.emerald.blackjack.ui.f789c4eb21db": " FP restants avant Amitié Niv {value1}",
  "aux.emerald.blackjack.ui.472984585f76": "Carte face cachée",
  "aux.emerald.blackjack.ui.2d19dec9aa43": "Prêt pour la donne",
  "aux.emerald.blackjack.ui.9bf2be15acf2": "Prêt quand vous le serez. Gagnez une manche pour obtenir 1 point.",
  "aux.emerald.blackjack.ui.b2916229c20a": "Battez Emerald sans dépasser 21 pour obtenir 1 point.",
  "aux.emerald.blackjack.ui.42ea85436e9f": " Quel plaisir de jouer ensemble — cette manche est à vous !",
  "aux.emerald.blackjack.ui.a475b3488a5a": " Je suis heureuse que nous jouions ensemble. Prenez votre temps pour la suivante.",
  "aux.emerald.blackjack.ui.fc8123bdfb07": " Vous pouvez y arriver. Profitons ensemble du prochain coup.",
  "aux.emerald.blackjack.ui.eecdfe7bdb54": " Votre coup a porté ses fruits !",
  "aux.emerald.blackjack.ui.2fb42ac6ba05": " Ma manche ! On en refait une ?",
  "aux.emerald.blackjack.ui.04a01324d5b2": " Voyons ce que donnera votre prochain coup.",
  "aux.emerald.blackjack.ui.40c7f8e473c9": "Amitié Niv",
  "aux.emerald.blackjack.ui.433af78c1585": "0 FP restants · Amitié maximale atteinte",
  "aux.emerald.blackjack.ui.5bf09aa55c26": " FP restants avant l’amitié maximale",
  "aux.emerald.blackjack.ui.0da47fae032a": "Emerald Niv",
  "aux.emerald.blackjack.ui.ecfb23c5e950": "Manche antérieure sauvegardée :",
  "aux.emerald.blackjack.ui.366da13a6382": "cette manche conserve son ancien décompte limité à 21 et son résultat sauvegardé. Le Blackjack normal commence à votre prochaine donne ; vos points de match et votre amitié existants sont conservés.",
  "aux.emerald.blackjack.ui.1892c889ec14": "Comment jouer au Blackjack",
  "aux.emerald.blackjack.ui.9a61529ef7cb": "Objectif :",
  "aux.emerald.blackjack.ui.05620ebe2577": "battez Emerald en vous approchant davantage de 21 sans le dépasser. Le total le plus élevé sans dépassement gagne ; si votre adversaire dépasse, vous gagnez. Dépasser 21 vous fait immédiatement perdre la manche. Des totaux égaux donnent une égalité.",
  "aux.emerald.blackjack.ui.2cb86993fe85": "Valeur des cartes :",
  "aux.emerald.blackjack.ui.73a6d3a088c6": "les cartes numérotées 2–10 valent leur valeur indiquée ; valet, dame et roi valent 10. Un as vaut 11 ou 1, selon ce qui donne le meilleur total sans dépassement. Une main souple contient un as encore compté pour 11.",
  "aux.emerald.blackjack.ui.bd5c7b75fc4f": "La donne :",
  "aux.emerald.blackjack.ui.4a70e9efecbf": "vous et Emerald recevez deux cartes chacun, dont une carte d’Emerald face cachée. Un as initial plus une carte de valeur 10 forme un Blackjack naturel : il bat un 21 ordinaire obtenu avec davantage de cartes. Deux Blackjacks naturels font égalité ; un seul naturel gagne immédiatement.",
  "aux.emerald.blackjack.ui.db0129e4cf75": "Votre tour :",
  "aux.emerald.blackjack.ui.bd063fccfe84": "Tirer prend une autre carte. Rester conserve votre main et termine votre tour. Vous pouvez continuer à tirer jusqu’à rester, dépasser ou atteindre 21. Atteindre 21 termine votre tour et résout la main d’Emerald ; ce n’est pas une victoire automatique si Emerald atteint aussi 21.",
  "aux.emerald.blackjack.ui.5668f90fc8d0": "Tour d’Emerald :",
  "aux.emerald.blackjack.ui.4d4dbf95e3b1": "la carte cachée est révélée ; Emerald tire en dessous de 17 et reste à 17 ou plus, y compris sur un 17 souple. Une fois les deux mains terminées, le total le plus élevé sans dépassement gagne. Si vous avez déjà dépassé, la manche se termine sans nouveau tour d’Emerald.",
  "aux.emerald.blackjack.ui.86f4fca99153": "Points du match :",
  "aux.emerald.blackjack.ui.17f2300a3af2": "chaque manche gagnée rapporte 1 point, même en dessous de 21. Une égalité ne rapporte aucun point. Le premier à 10 points remporte le match. Chaque manche terminée — victoire, défaite ou égalité — vous rapporte +1 point d’amitié (FP). Ouvrir un onglet, quitter ou recharger ne donne jamais un autre FP.",
  "aux.emerald.blackjack.ui.54406fb8245f": "Table amicale, sans mises :",
  "aux.emerald.blackjack.ui.bbb0975a9344": "les mises de casino, paiements 1:1 ou 3:2, doubler, séparer, abandonner et l’assurance indiqués dans les règles de référence ne sont pas utilisés ici. Le Blackjack ne dépense ni ne verse jamais d’argent sur votre solde de poker.",
  "aux.emerald.blackjack.ui.0291d43cec31": "Revenus passifs :",
  "aux.emerald.blackjack.ui.8028b08cabd4": "une fois débloqués et activés, ils ajoutent toujours $0.01 par seconde admissible au premier plan à votre solde de poker, y compris dans cet onglet. Le temps masqué ou écran verrouillé et les pauses protégées par sauvegarde/fenêtre modale ne rapportent rien.",
  "aux.emerald.blackjack.ui.c7a8d07745b6": "Aucune partie de poker active",
