  "aux.emerald.blackjack.ui.230e62edbe61": "Blackjack normal · gagnez une manche pour 1 point · premier à 10. Les égalités ne donnent aucun point. Chaque manche terminée rapporte +1 FP. Emerald reste à 17, y compris sur un 17 souple.",
