  "poker.exactBonus": "Objectif choisi atteint exactement : +100 XP +5 FP une seule fois, ajoutés à la récompense de la main obtenue. Un seul gain d’amitié partagé, pas un par place.",
  "poker.rewardPolicy": "Les récompenses indiquées sont des montants de base fixes : les multiplicateurs du niveau de poker ne modifient que les futures pièces du robinet, jamais ces gains, les FP ou les PXP. Toutes les pièces et médailles sont fictives. Seule la meilleure main standard paie, une seule fois ; une main sans paire dont la carte la plus haute est inférieure à 10 ne rapporte rien.",
  "poker.eventPolicy": "Le temps de l’événement continue de s’écouler lorsque la table est fermée. Répéter un événement prolonge sa durée jusqu’à l’échéance la plus tardive, sans cumuler les multiplicateurs. Les 100 réclamations de la quinte flush royale font seulement progresser le niveau du robinet : pas 100 gains de réclamation, ni tâches quotidiennes ou séries. La quinte flush royale divise par deux uniquement les délais de relance du jeu ; CAPTCHA, consentement, sécurité, animations, réinitialisations quotidiennes et cadences des cadeaux et des gains restent inchangés.",
