  "poker.interest.reward.42": "Les intérêts composés utilisent la réserve actuelle ×0,025%, sans plafond par paiement. Les900 ms d’origine restent sauf choix sauvegardé. La ligne de Réglages reste en lecture seule jusqu’au44 ; le niveau réel100 gagne0.",
  "poker.interest.compact.42": "Intérêts d’origine 900 ms · 5 XP/paiement + argent passif 20 min",
  "poker.interest.reward.43": "+1 à la taille de main. Les intérêts composés restent réserve actuelle × taux réel × bonus d’XP gagnés/Joker/Poker, sans plafond ;900 ms et ×0,025% restent sauf choix sauvegardé.",
  "poker.interest.compact.43": "+1 taille de main · intérêts composés sans plafond",
  "poker.interest.cap43.note": "Les intérêts composés utilisent la réserve actuelle d’XP non dépensés à CHAQUE paiement : taux d’origine0,01% aux niveaux réels20–25,0,015% aux26–29 et0,025% aux30–79 sauf choix sauvegardé ; dès80, cadence et taux acquis prennent le relais. Sans plafond. Les bonus d’XP gagnés, Joker Exp physique et Poker natif s’appliquent une fois. Un tirage reproductible par paiement réel : ×2 aux50–61 ; 10% de chance de×3 aux62–99. Chaque règlement conserve les coûts des niveaux franchis et utilise la réserve résultante précédente. Le niveau réel100 gagne0. Niveau15, manuel22, Potion Exp et bonus Slots non concernés ne multiplient pas les intérêts. Connaissance et intérêts en argent restent séparés. Anciens reçus et réserves inchangés. Temps visible admissible uniquement ; aucun rattrapage masqué, hors ligne ou au rechargement.",
