  "catalog.planets.venus_rock.name": "Venus Rock",
  "catalog.potions.all_suiter.activeDetail": "Toute carte non-Stone compte comme toutes les enseignes",
  "catalog.potions.all_suiter.description": "Pendant 120 secondes, toute carte non-Stone compte comme toutes les enseignes pour les mains, les effets de Joker et les règles d’enseigne des boss. Les enseignes imprimées ne changent pas. Stone reste sans enseigne.",
  "catalog.potions.all_suiter.name": "All-Suiter",
  "catalog.potions.blend.activeDetail": " · CRIT de base des potions combinées de 4.5% ; le niveau 32 ajoute 1pp ; probabilités finales plafonnées à 100%.",
  "catalog.potions.boss_disabler.activeDetail": "1 sur 20 fixe au début du boss · désactivation temporaire",
  "catalog.potions.boss_disabler.description": "Une seule tentative fixe de 1 sur 20 (5%) au début d’un vrai boss pendant l’effet actif de 120 secondes. La chance et Oops n’augmentent JAMAIS cette probabilité. Une désactivation temporaire réussie prend fin à l’expiration ou au remplacement de la potion, ou à la fin du boss. Aucun nouveau tirage à l’inspection, au rechargement ou à la synchronisation de l’horloge ; aucun bouton de désactivation par partie.",
  "catalog.potions.boss_disabler.name": "Boss-disabler Potion",
  "catalog.potions.chips.activeDetail": "+20 Chips / déclenchement de carte qui marque",
  "catalog.potions.chips.description": "Chaque déclenchement réel d’une carte qui marque donne +20 Chips pendant 120 secondes, redéclenchements compris. Les cartes non comptées ou gardées en main ne le reçoivent pas.",
  "catalog.potions.chips.name": "Chip Potion",
  "catalog.potions.cooldown.activeDetail": "½ new passive / faucet waits · Existing market deadlines stay unchanged.",
  "catalog.potions.cooldown.description": "Halves the current remaining passive-restart wait and coin-faucet wait once. An already-halved wait is never halved again by another bottle. New waits begun during the 120-second effect are also halved. Level 14 still applies. Expiry never lengthens a shortened deadline. Potion durations, animation and accepted Stock Market deadlines are NOT shortened (new predictions: 10 minutes before Level40, 60 seconds from Level40).",
  "catalog.potions.cooldown.name": "Cooldown Potion",
  "catalog.potions.critical.activeDetail": "CRIT de base de 2.5% · {value1}% actuellement / déclenchement de score · ×2 Mult",
  "catalog.potions.critical.description": "Pendant 120 secondes, chaque déclenchement réel de carte qui marque, redéclenchements compris, a une chance de base de 1 sur 40 d’infliger un CRIT de ×2 au Mult actuel. La chance indiquée la modifie. Cet effet est distinct de Critical Joker ; les cartes gardées en main, non comptées ou désactivées ne font jamais ce tirage de base.",
  "catalog.potions.critical.name": "Critical Potion",
  "catalog.potions.daylight.activeDetail": "+{value1} Mult à la FIN du calcul du score · pas ×day",
  "catalog.potions.daylight.description": "Ajoute le numéro du jour du mois actuel d’Atlantic/Canary sous forme de +Mult UNE SEULE FOIS, tout à la fin du calcul du score, pendant 120 secondes. Exemple : le 12, +12 Mult — PAS ×12.",
  "catalog.potions.daylight.name": "Daylight Potion",
  "catalog.potions.exp.activeDetail": "×2 XP nouvellement gagnée",
  "catalog.potions.exp.description": "Double l’XP ordinaire nouvellement gagnée pendant 120 secondes, y compris au robinet et dans les sondages ; les intérêts composés et Knowledge gardent leurs propres taux. Se cumule avec le bonus d’XP du niveau 15. Knowledge est une exception à taux fixe ; l’ancienne XP n’est jamais augmentée rétroactivement.",
  "catalog.potions.exp.name": "Exp Potion",
  "catalog.potions.gaming.activeDetail": "CRIT de base de 2% · {value1}% actuellement · perd 1 HP / carte sélectionnée",
  "catalog.potions.gaming.description": "Commence à 100 HP et donne, pendant 120 secondes, une chance de base de 1 sur 50 par déclenchement réel de carte qui marque d’infliger un CRIT de ×2 au Mult actuel. La chance indiquée modifie cette probabilité. Chaque main jouée valide perd autant de HP que le nombre exact de cartes sélectionnées, même si le boss interdit de marquer. À 0 HP, toute la partie est perdue avant tout paiement de victoire ou potion, et Gaming se termine. Les HP ne remontent jamais au rechargement ou en nouvelle partie. Vert >70 ; jaune ≤70 ; rouge ≤40.",
  "catalog.potions.gaming.name": "Gaming Potion",
  "catalog.potions.high_stonks.activeDetail": "$1 d’intérêts / $3 détenus · plafond normal",
  "catalog.potions.high_stonks.description": "Pendant 120 secondes, gagnez $1 d’intérêts par tranche de $3 détenus au lieu de $5. Les déblocages, plafonds et règles des bons liés aux intérêts restent applicables.",
  "catalog.potions.high_stonks.name": "High Stonks Potion",
  "catalog.potions.knowledge.activeDetail": "1 XP fixe / seconde · XP passive manuelle uniquement",
  "catalog.potions.knowledge.description": "Pendant qu’une session d’XP passive existante lancée manuellement verse des gains, accorde exactement 1 XP par seconde pendant 120 secondes. Ce gain fixe ignore le niveau 15, Exp Potion et le bonus manuel du niveau 22 ; les Exp Jokers physiques actifs le multiplient. Ne lance, ne relance et ne prolonge aucune session passive.",
  "catalog.potions.knowledge.name": "Knowledge Potion",
  "catalog.potions.luck.activeDetail": "×2 chance indiquée · obtention plafonnée à 50%",
