  "uiC.guide.consentAll": "I understand the terminal ending resets ALL THREE local save slots, including their levels, XP, coins, runs, daily progress, photos and settings.",
  "uiC.guide.consentBackup": "I require a lasting verified backup outside the erased game banks, with download and explicit recovery. I will keep browser data; storage is not guaranteed against browser/device clearing.",
  "uiC.guide.consentFiction": "This is optional fictional cartoon acting, not a real relationship or a punishment for taking breaks. Pause, Show tips, Looker and cancel remain available; there are no gifts, random rolls or rewards.",
  "uiC.guide.storyBackupsButton": "Optional story & lasting backups",
  "uiC.guide.storyDisable": "Disable optional story (keep all progress)",
  "uiC.guide.storyEnroll": "Enroll only this slot",
  "uiC.guide.storyEnrolled": "This slot is enrolled. Show tips / Looker / unquiet cancels the current episode; disabling also opts this slot out.",
  "uiC.guide.storyForeign": "An imported story record is not bound here and has no authority. Enrollment replaces only that optional record, never your earned progress.",
  "uiC.guide.storyNoTimer": "No timer erases anything.",
  "uiC.guide.storyProjectionSafety": "The staged disappearing UI is only a projection. The terminal action needs renewed typed ALL THREE consent and a verified lasting backup BEFORE any canonical erase. Accounts, remote saves and local conduct restrictions are not erased. Taking any break is fine.",
  "uiC.guide.storyRecoveryTitle": "Optional story · lasting recovery",
  "uiC.guide.storySummary": "Ordinary Quiet is unchanged. A separate fictional story is off unless this slot opts in at actual Level 5+. Breaks are always fine; no game rewards or penalties come from its timers.",
  "uiC.guide.storyTimeline": "Plain Quiet remains plain Quiet unless you enroll this local slot. At 24 hours of Quiet: 10 minutes of wording only. At 7 days: one hour of optional cartoon tears. At 28 days: a queued fictional Revenge scene, beginning only after a guarded save at the actual Choose Your Deck screen. Offline real time counts; changing the clock backwards cannot rewind saved time. Only the highest unseen milestone is shown.",
  "uiC.guide.storyTitle": "Optional Emerald story",
  "uiC.guide.storyUnlock": "Enrollment unlocks at actual player Level 5. Recovery downloads below remain available.",
  "uiC.hand.base": "Base : {chips} Jetons fois {mult} Mult",
  "uiC.hand.chips": "{n} Jetons",
  "uiC.hand.level": "Niveau {n}",
  "uiC.hand.levelShort": "Niv. {n}",
  "uiC.help.audio": "Le premier appui active la musique lounge originale et les sons de cartes/score. Appuyez sur le bouton musique ou sur M pour couper le son ; les Paramètres proposent des commandes et volumes séparés pour musique/effets. Aucun fichier audio n’est téléchargé.",
  "uiC.help.audioLabel": "Son :",
  "uiC.help.bosses": "Les boss ont des règles spéciales. Lisez-les avant de vous engager.",
  "uiC.help.controls": "Appuyez sur un Joker pour l’inspecter. Maintenez une carte à jouer pour voir ses détails. Utilisez les flèches de la fiche d’inspection pour réordonner. Appuyez sur I lorsqu’une carte a le focus pour l’inspecter. Les boutons de tri réordonnent votre main.",
  "uiC.help.controlsLabel": "Commandes :",
  "uiC.help.discard": "Discard up to {limit} cards at a time to look for a better hand.",
  "uiC.help.fileHint": "L’aperçu des fichiers téléchargés utilise un stockage dépendant du navigateur. Exportez des copies et utilisez la même URL hébergée pour reprendre de façon fiable.",
  "uiC.help.formula": "Chips × Mult",
  "uiC.help.goalBlinds": "8 Antes × 3 blindes",
  "uiC.help.goalEnd": ": petite, grosse et boss. Battez le boss de l’Ante 8 pour gagner.",
  "uiC.help.goalStart": "Atteignez assez de points avant d’épuiser vos mains. Une partie comporte",
  "uiC.help.order": "before-play effects → scoring cards and their retriggers → held-in-hand effects → independent Jokers. +Mult before ×Mult helps only when the effects share a timing window.",
  "uiC.help.orderLabel": "Ordre de calcul du score :",
  "uiC.help.planets": "Planets level up hands; Jokers change how you score.",
  "uiC.help.play": "Jouer la main",
  "uiC.help.potionGuide": "Mode d’emploi · les 16 effets de potion",
  "uiC.help.potions": "Conservez deux bouteilles, avec un seul effet actif pendant exactement 120 secondes réelles. Inspecter ne fait jamais boire. Une confirmation explicite est requise, y compris pour remplacer. Les boss donnent une potion avec une chance de base de 1 sur 10, plafonnée à 50% avec la chance ; Boss Disabler reste à 1 sur 20. Les minuteries et les HP de Gaming persistent après rechargement et nouvelle partie.",
  "uiC.help.potionsLabel": "Potions · Niveau 12 :",
  "uiC.help.save": "La progression et les statistiques s’enregistrent automatiquement dans ce navigateur. Téléchargez/exportez une copie dans les Paramètres. Il s’agit d’une base solo privilégiant le stockage local, pas d’un jeu multijoueur ni d’un produit Balatro officiel.",
  "uiC.help.saveLabel": "Sauvegarde :",
  "uiC.help.score": "Score =",
  "uiC.help.scoringCards": "Only cards belonging to the poker hand normally score.",
  "uiC.help.select": "Tap 1–{limit} cards, then",
  "uiC.help.shop": "Après une victoire, encaissez et améliorez votre jeu dans la boutique. Passer une petite/grosse blinde échange la manche et la boutique contre une étiquette.",
  "uiC.help.title": "Les règles de la table",
  "uiC.identity.available": "Change this save’s nickname with Change username → Confirm.",
  "uiC.identity.cancel": "Annuler",
  "uiC.identity.change": "Changer de pseudo",
  "uiC.identity.confirm": "Confirmer",
  "uiC.identity.generation": "Le pseudo aléatoire initial est calculé localement à partir de la génération de cet emplacement, sans sauvegarde supplémentaire ni tirage dans le générateur aléatoire du jeu. Un pseudo personnalisé confirmé est conservé dans les paramètres de cet emplacement et n’est inclus que lors d’une exportation ou d’une sauvegarde cloud manuelle. Le pseudo généré au départ n’est pas une identité cloud.",
  "uiC.identity.label": "Nouveau pseudo",
  "uiC.identity.locked": "Reach actual Player Level 2 to unlock Change username.",
  "uiC.identity.notSaved": "Rien n’est enregistré avant votre confirmation.",
  "uiC.identity.off": "Username display is disabled in feature settings. Your saved nickname is kept.",
  "uiC.identity.privacy": "Use an invented nickname, not your real name or private details. This is not an account, authentication or a globally unique name.",
  "uiC.identity.rules": "Utilisez un pseudo inventé, sans données personnelles. Longueur : 3–24 caractères, parmi les lettres ASCII, les chiffres, les traits de soulignement et les traits d’union. Les noms ne sont pas uniques à l’échelle mondiale et n’identifient pas un compte cloud.",
  "uiC.identity.title": "Pseudo · Niveau 2",
  "uiC.images.background": "Background image",
  "uiC.images.cardBack": "Card-back image",
  "uiC.images.faceCard": "Face-card photo (J, Q, K)",
  "uiC.images.help": "JPEG, PNG or WebP · up to 12 MB and 24 MP (8,192 px per side). Images are resized, compressed and stripped of metadata. Backgrounds fit within 1,280 px; card backs and face-card photos within 512 px. Each image is compressed to about 45 KB or less; detailed images may be resized further.",
  "uiC.images.intro": "Make this table yours. Your face-card photo replaces the central art on Jacks, Queens and Kings. Ranks, suits, modifiers and gameplay stay unchanged. Card-back art applies only to hidden cards.",
  "uiC.images.level": "· Level 30 cosmetics",
  "uiC.images.locked": "Unlocks at Level 30",
  "uiC.images.lockedIntro": "Reach actual Player Level 30 to choose your own background, playing-card back and face-card photo. Earlier rewards stay active.",
