  "uiC.music.afterLicense": ". Original recordings included locally; George Street Shuffle and Mining by Moonlight unlock at Player 36. Boss and Last Chance modes add original backing and playback processing; Frenzy plays its own original score. No endorsement implied.",
  "uiC.music.and": ", and ",
  "uiC.music.asset.loading": " · Loading local recording…",
  "uiC.music.asset.originalFallback": " · Recording unavailable; original synthesized fallback",
  "uiC.music.asset.rouletteFallback": " · Recording unavailable; original roulette fallback",
  "uiC.music.header.base": "Soundtrack · originals + Deadly Roulette at Level 2 · classic casino at 24 · two more at 27",
  "uiC.music.header.level36": "Soundtrack · Player 36 playlist + two extra licensed recordings · classic casino at 24 · two more at 27",
  "uiC.music.header.level58": "Soundtrack · ten new Level 58 originals + Player 36 playlist · classic casino at 24 · two more at 27",
  "uiC.music.intro": "Original arcade, roulette, casino, poker and blackjack compositions, plus the licensed recordings below. Level 58 adds ten locally synthesized original scores: neo-soul, downtempo, nu-disco, broken beat, acoustic, chamber groove, Lydian jazz, ambient dub, chip-funk and swing. Boss Blinds switch to darker arrangements; Ante 8+ Boss Blinds add a final-boss climax. Level 5 unlocks emotional Last Chance music with 1 hand and no discards left. Your selected track returns afterward. Level 37 adds more dramatic Boss arrangements; table, Last Chance and Frenzy keep their own arrangements. Not the official Balatro soundtrack.",
  "uiC.music.license": "Creative Commons Attribution 4.0",
  "uiC.music.licensedUnder": ". Licensed under ",
