  "uiC.potions.capacity.drop": "Base1sur10 par Boss vaincu, chance indiquée appliquée jusqu’à50%. Un butin choisit uniformément parmi16 types. Aucune bouteille en plus lorsque tes {capacity} emplacements sont pleins.",
