  "uiC.recovery.export": "Export recovery evidence",
  "uiC.recovery.note": "Do not retry the action or clear data. Reload checks retained journals before models load. Read-only evidence export does not repair or change any bank.",
  "uiC.restore.confirm": "Restore all three from backup",
  "uiC.restore.keep": "Keep current saves",
  "uiC.restore.summary": "This replaces ALL THREE current local saves with the verified pre-ending saves, and captures the complete newer saves in a DIFFERENT lasting backup first. The original backup is never overwritten. The restored optional story is disabled so the ending cannot replay. Restore is refused after any of the three target generations has been independently replaced.",
  "uiC.restore.title": "Restore ALL THREE saves?",
  "uiC.restore.typed": "Type RESTORE ALL 3 exactly",
  "uiC.rewards.after.aux.levels.ui.9cf1b5d5fea3": " · Coûts futurs en XP réduits de 30% supplémentaires dès 30→31 ; se cumule avec la division par deux du niveau 10 et la réduction du niveau 20 (21% de l’original avant arrondi entier et potions) ; aucun remboursement · Photos personnalisées des figures (J/Q/K) · Interface améliorée et couleurs de table enrichies · Importez vos images de fond et de dos de carte · Personnalisez police et couleur de tous les textes dans les Paramètres ; réinitialisez le texte sans modifier les photos ni la disposition des panneaux",
  "uiC.rewards.beetle.aux.levels.ui.172c3a8a5b8f": "a green beetle : appuyez sur la photo ou la barre de progression pour sa propre feuille de route, avec le niveau actuel encadré ; progression et pourcentage des nouvelles victoires · Parole automatique pendant 5 minutes, puis 1 minute d’attente · Enregistrements sous licence de George Street Shuffle et Mining by Moonlight ; Poker Face ouvre exactement le titre officiel Spotify en externe, pas un son hors ligne",
  "uiC.rewards.beetle.aux.levels.ui.4091e1349b2d": "a green beetle reflète un éclat vert émeraude renforcé",
  "uiC.rewards.beetle.aux.levels.ui.5e10e5839a2d": " · Progression d’a green beetle débloquée : barre verte E1–E10 sous la photo pendant une partie ; les nouvelles victoires complètes obtenues au niveau réel 10+ font avancer chaque étape",
  "uiC.rewards.beetle.aux.levels.ui.c0955075c2a3": "a green beetle apparaît sur tous les écrans, sondages compris · Exactement “Trick Question!!!” uniquement sur une véritable question de vérification d’attention",
  "uiC.rewards.beetle.emerald.quirk.unlock": "Dès le niveau 6 du joueur, chaque nouveau message d’a green beetle a une chance sur 6 d’avoir un tic de texte, choisi à parts égales parmi six sons, y compris au Blackjack. Aucun audio.",
  "uiC.rewards.beetle.expansion.reward.48": "a green beetle se déplace 50 % plus vite en plus de son bonus E3 : ×1,5, ou ×1,8 avec E3. Les préférences de mouvement restent respectées. Sans choix personnalisé sauvegardé, les intérêts d’origine paient toutes les600 ms à ×0,025 %, sans plafond par paiement. Un choix sauvegardé remplace l’intervalle et le taux d’origine ; la ligne de Réglages modifie le même flux unique. Le niveau réel100 gagne0.",
  "uiC.rewards.beetle.expansion.reward.49": "a green beetle gagne plus de 1 000 messages originaux et contextuels en anglais, espagnol et français : cartes, jeux, réflexions bienveillantes et idées respectueuses inspirées de la Bible. Il ne commente une enquête terminée qu’avec un reçu réel ; aucune prédiction de carte cachée ni du hasard.",
  "uiC.rewards.beetle.uiC.rewards.companion5": " · Compagnon a green beetle : conseils de jeu et encouragements",
  "uiC.rewards.before.aux.levels.ui.6ee23633b64b": "Coûts futurs en XP réduits de 40% supplémentaires, cumulables avec le niveau 10 (30% des coûts d’origine) ; aucun remboursement · +1 main et défausse à chaque boss · Interface plus claire et boutons plus fluides · couleurs enrichies et lueurs douces · montants en dollars jaunes · petite blinde bleue, grosse jaune, boss rouge · ",
  "uiC.rewards.before.aux.levels.ui.f56e82a7ade0": "Mode déplacement · enregistrement des dispositions de panneaux mobiles · Thèmes de table personnalisés · XP requise pour tous les niveaux divisée par deux · ",
  "uiC.rewards.before.aux.levels.ui.fd983ce532d1": "Interface des niveaux de joueur améliorée · XP, récompenses et états terminés/verrouillés plus clairs · animations vertes de gain +XP et reflet blanc rebondissant sur la barre d’XP · ",
  "uiC.rewards.companion5": " · Compagnon Emerald : conseils de jeu et encouragements",
  "uiC.rewards.crit": "Permanent +1% CRIT per actual scoring card trigger",
  "uiC.rewards.late.100": "Maximum Level100! Continue this save or explicitly start Savefile2.",
  "uiC.rewards.late.56": "The Coin Faucet no longer asks a Balatro question. CAPTCHA remains.",
  "uiC.rewards.late.57": "+10% relative luck (x1.10 on earned x1.25 = x1.375).",
  "uiC.rewards.late.58": "Ten more original soundtracks.",
  "uiC.rewards.late.59": "Normal starting run money is $10. Yellow and Erratic special starts stay special.",
  "uiC.rewards.late.60": "Foods and Darts. Earn one food ticket for every two completed Antes; View the bar in the shop.",
  "uiC.rewards.late.61": "Cleaner, more readable game and card-game tables.",
  "uiC.rewards.late.62": "More fonts to personalise your table.",
  "uiC.rewards.late.80": "Earned interest takes over; Interest and Feature power Settings sections are retired without deleting saved choices.",
  "uiC.rewards.level10Deal": "Optional Level10 deal (toggle in Settings): +1 hand size, ×1.05 final chips and ×1.01 final Mult, for -$3 at round end while enabled",
  "uiC.rewards.level18Precision": "Settings: XP display precision 0–10 decimal places (default 5), display only",
  "uiC.rewards.level6": "Blind targets 2.5% lower (×0.975), independent of the Level8 reduction",
  "uiC.rewards.level8": "Blind targets another 5% lower (×0.95), independent of Level6 (×0.975); both reductions multiply independently",
  "uiC.rewards.money.aux.levels.ui.268db3145f3b.1": "+$2",
  "uiC.rewards.money.aux.levels.ui.268db3145f3b.2": " à la fin de chaque manche gagnée",
  "uiC.rewards.money.aux.levels.ui.4c33d5827537.1": "+$1",
  "uiC.rewards.money.aux.levels.ui.4c33d5827537.2": " à chaque encaissement de manche gagnée",
  "uiC.rewards.money.aux.levels.ui.6251513eba38.0": "Débloque les sondages Bitlabs · Gagnez ",
  "uiC.rewards.money.aux.levels.ui.6251513eba38.1": "$1",
  "uiC.rewards.money.aux.levels.ui.6251513eba38.2": " à chaque déclenchement d’un effet spécial de boss actif · une récompense par activation de capacité, pas par carte affectée",
  "uiC.rewards.money.aux.levels.ui.7d1c4602dc17.0": "Revenus passifs sous le robinet de pièces, reprenant la disposition de l’XP passive avec lueur jaune et symboles $ € £ · ",
  "uiC.rewards.money.aux.levels.ui.7d1c4602dc17.1": "+$0.01",
  "uiC.rewards.money.aux.levels.ui.7d1c4602dc17.2": " par seconde observable au premier plan vers le solde de la partie actuelle pendant 10 minutes, puis 5 minutes d’attente · Un solde plus élevé donne un son d’argent plus aigu ; aucun rattrapage hors ligne",
  "uiC.rewards.money.aux.levels.ui.b22c96f74381.0": "Tout dans la boutique de partie coûte ",
  "uiC.rewards.money.aux.levels.ui.b22c96f74381.1": "$1",
  "uiC.rewards.money.aux.levels.ui.b22c96f74381.2": " de moins après les remises existantes ; minimum ",
