  "uiC.rewards.money.expansion.reward.47.1": "$20",
  "uiC.rewards.money.expansion.reward.47.2": " fictifs selon le niveau réel du joueur. Délai de dix minutes, risques, retour brut ×1,5 et absence d’argent réel restent inchangés.",
  "uiC.rewards.money.uiC.rewards.level10Deal.0": "Optional Level10 deal (toggle in Settings): +1 hand size, ×1.05 final chips and ×1.01 final Mult, for ",
  "uiC.rewards.money.uiC.rewards.level10Deal.1": "-$3",
  "uiC.rewards.money.uiC.rewards.level10Deal.2": " at round end while enabled",
  "uiC.rewards.money.uiC.rewards.updated.19.0": "Sondages Bitlabs · Tous les nouveaux paquets proposent une option en plus, pas un choix en plus. Remplace le gain de ",
  "uiC.rewards.money.uiC.rewards.updated.19.1": "$1",
  "uiC.rewards.money.uiC.rewards.updated.19.2": " des effets du Boss.",
  "uiC.rewards.money.uiC.rewards.updated.47.0": "Garde4 potions · Mise boursière maximale ",
  "uiC.rewards.money.uiC.rewards.updated.47.1": "$20",
  "uiC.rewards.money.uiC.rewards.updated.47.2": " fictifs ; les nouvelles prédictions dès le niveau40 durent60s, les anciennes gardent leur échéance",
  "uiC.rewards.money.uiC.rewards.updated.6.0": "Les nouvelles parties commencent avec ",
  "uiC.rewards.money.uiC.rewards.updated.6.1": "$5",
  "uiC.rewards.money.uiC.rewards.updated.6.2": " au lieu de ",
  "uiC.rewards.money.uiC.rewards.updated.6.3": "$4",
  "uiC.rewards.unknown.aux.levels.ui.172c3a8a5b8f": "??? : appuyez sur la photo ou la barre de progression pour sa propre feuille de route, avec le niveau actuel encadré ; progression et pourcentage des nouvelles victoires · Parole automatique pendant 5 minutes, puis 1 minute d’attente · Enregistrements sous licence de George Street Shuffle et Mining by Moonlight ; Poker Face ouvre exactement le titre officiel Spotify en externe, pas un son hors ligne",
  "uiC.rewards.unknown.aux.levels.ui.4091e1349b2d": "??? reflète un éclat vert émeraude renforcé",
  "uiC.rewards.unknown.aux.levels.ui.5e10e5839a2d": " · Progression d’??? débloquée : barre verte E1–E10 sous la photo pendant une partie ; les nouvelles victoires complètes obtenues au niveau réel 10+ font avancer chaque étape",
  "uiC.rewards.unknown.aux.levels.ui.c0955075c2a3": "??? apparaît sur tous les écrans, sondages compris · Exactement “Trick Question!!!” uniquement sur une véritable question de vérification d’attention",
  "uiC.rewards.unknown.emerald.quirk.unlock": "Dès le niveau 6 du joueur, chaque nouveau message d’??? a une chance sur 6 d’avoir un tic de texte, choisi à parts égales parmi six sons, y compris au Blackjack. Aucun audio.",
  "uiC.rewards.unknown.expansion.reward.48": "??? se déplace 50 % plus vite en plus de son bonus E3 : ×1,5, ou ×1,8 avec E3. Les préférences de mouvement restent respectées. Sans choix personnalisé sauvegardé, les intérêts d’origine paient toutes les600 ms à ×0,025 %, sans plafond par paiement. Un choix sauvegardé remplace l’intervalle et le taux d’origine ; la ligne de Réglages modifie le même flux unique. Le niveau réel100 gagne0.",
  "uiC.rewards.unknown.expansion.reward.49": "??? gagne plus de 1 000 messages originaux et contextuels en anglais, espagnol et français : cartes, jeux, réflexions bienveillantes et idées respectueuses inspirées de la Bible. Il ne commente une enquête terminée qu’avec un reçu réel ; aucune prédiction de carte cachée ni du hasard.",
  "uiC.rewards.unknown.uiC.rewards.companion5": " · Compagnon ??? : conseils de jeu et encouragements",
  "uiC.rewards.updated.19": "Sondages Bitlabs · Tous les nouveaux paquets proposent une option en plus, pas un choix en plus. Remplace le gain de $1 des effets du Boss.",
  "uiC.rewards.updated.3": "Fenêtre de niveau colorée avec flèches bleues",
  "uiC.rewards.updated.31": "+10% d’XP des actions Balatro uniquement · Voir la partie abandonnée donne des conseils fondés sur cette partie",
  "uiC.rewards.updated.34": "Statistiques enrichies, onglets colorés et analyses fondées sur les données",
  "uiC.rewards.updated.40": "Coûts futurs d’XP −20%, sauf atteindre le niveau50 · Garde3 potions · Nouvelles prédictions boursières60s · CAPTCHA du robinet à cinq caractères · Couleurs des barres selon leur niveau",
  "uiC.rewards.updated.47": "Garde4 potions · Mise boursière maximale $20 fictifs ; les nouvelles prédictions dès le niveau40 durent60s, les anciennes gardent leur échéance",
  "uiC.rewards.updated.50": "Encore −10% aux coûts futurs d’XP ; le niveau40 reste actif · Maximum du joueur100 · Jeux, Poker strict et Machine à sous",
  "uiC.rewards.updated.6": "Les nouvelles parties commencent avec $5 au lieu de $4",
  "uiC.rewards.updated.7": "Suffixes numériques : K rouge · M orange · B jaune · T vert",
  "uiC.rewards.updated.8": "Le retour au menu ouvre Choisir un paquet",
  "uiC.settings.dealLocked": "The optional Level 10 deal unlocks at Level 10.",
  "uiC.settings.dealOff": "Level 10 deal: OFF",
  "uiC.settings.dealOn": "Level 10 deal: ON",
  "uiC.settings.dealRules": "Optional deal: +1 Hand Size, +5% final Chips and +1% final Mult; −$3 when a round ends. Toggle again to remove all deal buffs and future taxes. The extra hand slot fills on the next normal draw; already-dealt cards stay in hand. Finished-round taxes are not refunded.",
  "uiC.settings.dealTitle": "ON: +1 Hand Size, final Chips ×1.05 and final Mult ×1.01; pay $3 when a round ends. OFF: no deal buffs or future tax.",
  "uiC.settings.decimalsLocked": "Unlocks at Level 18. ",
  "uiC.settings.decimalsNote": "Nombre de décimales affichées : 0–10 ; les zéros finaux sont supprimés. Votre XP réelle conserve toute sa précision.",
  "uiC.settings.declaredLink": "Explicit declared-progress recovery & raw three-slot backup",
  "uiC.settings.declaredNote": "A declared-recovery JSON is not an earned-history save. Close other game tabs normally first; this separate page does not initialize or reset a slot.",
  "uiC.settings.luck17": "Chance de niveau 17 active : +25% (×1.25).",
  "uiC.settings.luck57": "Level 57 luck active: relative +10% on Level 17 luck (×1.25 ×1.10 = ×1.375; +37.5% total).",
  "uiC.settings.luckLocked": "Le niveau 17 débloque +25% de chance (×1.25).",
  "uiC.settings.luckRules": " Les probabilités indiquées se cumulent avec chaque Oops actif ×2 et une Luck Potion active ×2, jusqu’à 100%. Les potions de boss sont plafonnées à 50% ; Boss Disabler reste à 1 sur 20. La rareté et les éditions de la boutique ne changent pas. La collection affiche les probabilités de base.",
