  "uiC.story.quiet": "Quiet again · restart cartoon hour",
  "uiC.story.quote.boss": "THIS POKER TABLE BELONGS TO ME NOW EH? WHOS THE BOSS NOW!!!!",
  "uiC.story.quote.decks": "YOU STILL HAVE DECKS TO PLAY WITH, HUH!? NOT ANYMORE!!!!!!!",
  "uiC.story.quote.distractions": "THESE CAUSE YOU TO DOOM SCROLL, DUMBASS YOU DONT EVEN HAVE A LEVEL!!!",
  "uiC.story.quote.ending": "You have found an ending... Emerald's Revenge! But there is still 1 other Ending for this game...",
  "uiC.story.quote.faucet": "FAUCET ALL TO MYSELF!!!",
  "uiC.story.quote.go": "GO TO THE CHOOSE YOUR DECK RIGHT NOW!!!",
  "uiC.story.quote.noLevels": "YOU HAVE NO LEVELS...",
  "uiC.story.quote.threat": "THAT'S IT!!! I WILL EAT ALL YOUR LEVELS, SUCK THE LIFE OUT OF THIS STUPID FAUCET, AND WRECK THIS TABLE WITH BALATRO FOR GOOD!!!",
  "uiC.story.resetBackup": "A verified full beforeimage is saved outside the erased game banks FIRST, with read-only download and explicit three-save recovery. It is never overwritten. Browser/device clearing can still lose local storage: keep a downloaded copy.",
  "uiC.story.resetCancel": "Back to ending",
