  "uiC.story.resetToken": "Type RESET ALL 3 exactly",
  "uiC.story.resetWarning": "This is the only destructive action in this optional story. Levels, XP, coins, runs, daily progress, photos and settings in ALL THREE local slots will reset. Accounts, remote saves and local conduct restrictions are not deleted.",
  "uiC.story.resume": "Resume story",
